def max_accordion_length(s: str) -> int:
    n = len(s)
    if n < 4:
        return -1

    # Initialize DP table
    dp = [[-1] * n for _ in range(n)]

    # Base cases for single characters
    for i in range(n):
        if s[i] == '[':
            dp[i][i] = 0
        elif s[i] == ']':
            dp[i][i] = -1

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if s[i] == '[' and s[j] == ']':
                if length == 2:
                    dp[i][j] = 2
                elif length == 4:
                    dp[i][j] = 4
                else:
                    for k in range(i + 1, j):
                        if dp[i + 1][k - 1] != -1:
                            dp[i][j] = max(dp[i][j], dp[i + 1][k - 1] + 4)

            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k], dp[k + 1][j])

    # Find the maximum length
    max_length = -1
    for i in range(n):
        for j in range(i, n):
            max_length = max(max_length, dp[i][j])

    return max_length

